import {coreLessons,fundamentals,advancedCore,collegeCore} from './curriculum.js';
import {coachingFor} from './coaching.js';
import {questionBankFor,drawCheckpoint} from './question-banks.js';
import {fullPlayTeachingCard} from './play-structure.js';
import {positions,positionLessons,electiveLessons} from './positions.js';
import {playOptions,defenses,playDiagram,driveField,filmCases,situations} from './labs.js';
import {designerStudio,filmStudio,simulatorStudio,setupStudio,studioClick,studioChange,resetStudioForDifficulty,stopStudio} from './studio-ui.js';

const STORAGE='football-academy-state-v1';
const ALL=[...coreLessons,...positionLessons,...electiveLessons];
const byId=Object.fromEntries(ALL.map(l=>[l.id,l]));
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const now=()=>new Date().toISOString();
const I={
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 7c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V6c-3-1-6-1-9 1z"/><path d="M12 7v14"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2"/><circle cx="18" cy="9" r="2"/><path d="M16 15c3 0 5 2 5 5"/>',strategy:'<path d="M4 5h6v6H4zM14 13h6v6h-6z"/><path d="M10 8h6v5M9 11v5h5"/>',play:'<path d="m8 5 11 7-11 7z"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M8 4l4 6M15 4l4 6"/>',chart:'<path d="M4 20V4M4 20h17M8 16v-4M13 16V8M18 16V6"/>',settings:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6l1.5 1.5m9.8 9.8 1.5 1.5M18.4 5.6l-1.5 1.5m-9.8 9.8-1.5 1.5"/><circle cx="12" cy="12" r="4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',moon:'<path d="M20 15.1A8 8 0 0 1 8.9 4 8.2 8.2 0 1 0 20 15.1Z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',left:'<path d="M19 12H5m6 6-6-6 6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',star:'<path d="m12 2 3 6 7 .9-5 4.9 1.2 7-6.2-3.3-6.2 3.3 1.2-7-5-4.9 7-.9z"/>',trophy:'<path d="M8 21h8M12 17v4M7 4h10v6a5 5 0 0 1-10 0zM7 6H3v2a4 4 0 0 0 4 4m10-6h4v2a4 4 0 0 1-4 4"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 17V5m-4 4 4-4 4 4M4 17v4h16v-4"/>',plus:'<path d="M12 4v16M4 12h16"/>',refresh:'<path d="M3 11a9 9 0 1 1 3 7M3 4v7h7"/>',shield:'<path d="m12 2 9 4v6c0 6-4 9-9 10-5-1-9-4-9-10V6z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',field:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M9 5v14m6-14v14M3 12h18"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 3h6v4H9zM8 12h8m-8 4h6"/>',bolt:'<path d="m14 2-9 11h7l-2 9 9-12h-7z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',chevron:'<path d="m9 18 6-6-6-6"/>',flag:'<path d="M5 22V4m0 1c3-2 6 2 9 0s5 0 5 0v10s-3-2-6 0-5-2-8 0"/>',pause:'<path d="M8 5v14M16 5v14"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14"/>',zap:'<path d="M13 2 4 13h7l-1 9 10-12h-7z"/>'
};
const icon=(name,cls='')=>`<svg class="ic ${cls}" viewBox="0 0 24 24" aria-hidden="true">${I[name]||I.star}</svg>`;
function readStore(){try{const v=JSON.parse(localStorage.getItem(STORAGE));if(v&&Array.isArray(v.profiles)&&['light','dark'].includes(v.theme))return v}catch{}return {theme:'dark',profiles:[],activeId:null};}
let db=readStore();
function person(){return db.profiles.find(p=>p.id===db.activeId)||db.profiles[0]||null}
function write(){try{localStorage.setItem(STORAGE,JSON.stringify(db));return true}catch{notify('This browser could not save progress. Export your backup from Settings.');return false}}
function createPerson(name){const p={id:'student-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name:name.trim().slice(0,40),completed:{},xp:0,practiceLevel:'rookie',created:now()};db.profiles.push(p);db.activeId=p.id;write();return p}
const model={view:'dashboard',positionId:'qb',filter:'All',lessonId:null,concept:0,quiz:null,menu:false,dialog:null,toast:'',playId:'slants',defenseId:'cover2',playStep:0,playHighlight:'',filmId:'motion',filmStep:0,filmAnswer:null,sim:null};
let deferredInstall=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;render()});
window.addEventListener('appinstalled',()=>{deferredInstall=null;notify('Football Academy installed. Good work, recruit.')});
function notify(s){model.toast=s;render();clearTimeout(notify.timer);notify.timer=setTimeout(()=>{model.toast='';render()},4400)}
function done(id){return !!person()?.completed?.[id]?.passed}
function completion(){return ALL.filter(l=>done(l.id)).length}
function isUnlocked(l){if(!l)return false;if(l.id==='core-1')return true;if(l.id.startsWith('core-'))return done(`core-${l.number-1}`);if(l.positionId)return done('core-6')&&(l.tier===1||done(`pos-${l.positionId}-${l.tier-1}`));return done('core-10')}
function nextLesson(){return coreLessons.find(l=>!done(l.id))||positionLessons.find(l=>!done(l.id)&&isUnlocked(l))||electiveLessons.find(l=>!done(l.id))||coreLessons[0]}
function completedCount(arr){return arr.filter(l=>done(l.id)).length}
function points(){return person()?.xp||0}
function saveCompletion(l,score){const p=person();if(!p)return;const prev=p.completed[l.id]||{attempts:0,best:0,passed:false};const passed=score>=80;const first=passed&&!prev.passed;p.completed[l.id]={attempts:prev.attempts+1,best:Math.max(prev.best,score),passed:prev.passed||passed,last:now()};if(first)p.xp+=(l.positionId?80:l.id.startsWith('elect-')?100:100);write()}
function navigate(view){stopStudio();model.view=view;model.menu=false;model.dialog=null;window.scrollTo({top:0,behavior:'instant'});render()}
function openLesson(id){const l=byId[id];if(!l||!isUnlocked(l)){notify('Complete the previous required lesson to unlock this one.');return}model.view='lesson';model.lessonId=id;model.concept=0;model.quiz=null;model.menu=false;window.scrollTo({top:0,behavior:'instant'});render()}
function navButton(label,view,iconName){return `<button class="nav-item ${(model.view===view||(view==='positions'&&model.view==='position'))?'active':''}" data-go="${view}" aria-current="${model.view===view?'page':'false'}">${icon(iconName)}${label}${model.view===view?'<span class="nav-dot"></span>':''}</button>`}
function header(){const p=person();return `<div class="mobile-backdrop ${model.menu?'active':''}" data-action="close-menu"></div><div class="layout"><aside class="sidebar ${model.menu?'open':''}" aria-label="Main navigation"><div class="brand"><div class="brand-icon">FA</div><div><div class="brand-name">FOOTBALL<br>ACADEMY</div><div class="brand-sub">The IQ Playbook</div></div></div><div class="caps nav-group">Your journey</div>${navButton('Command Center','dashboard','home')}${navButton('Core Course','course','book')}${navButton('Position Academy','positions','users')}<div class="caps nav-group">Practice & mastery</div>${navButton('Play Designer','designer','strategy')}${navButton('Coach Simulator','simulator','play')}${navButton('Film Room','film','film')}<div class="caps nav-group">Your account</div>${navButton('My Progress','progress','chart')}${navButton('Settings','settings','settings')}<div class="side-bottom"><div class="profile-pill"><div class="avatar">${E(p?.name?.charAt(0)?.toUpperCase()||'?')}</div><div style="min-width:0;flex:1"><div class="profile-name">${E(p?.name||'New student')}</div><div class="profile-caption">${points()} XP earned</div></div><button class="round-btn" title="Edit profile" aria-label="Edit profile" data-go="settings">${icon('settings')}</button></div></div></aside><div class="main"><header class="topbar"><div class="flex"><button class="round-btn top-mobile-menu" aria-label="Open navigation" data-action="toggle-menu">${icon('menu')}</button><div class="breadcrumb">FOOTBALL ACADEMY <span style="color:var(--soft)">/</span> ${E(labelForView())}</div></div><div class="topbar-actions"><span class="chip success">${icon('bolt')} ${points()} XP</span><button class="round-btn" data-action="toggle-theme" aria-label="Toggle light and dark theme" title="Toggle theme">${icon(db.theme==='dark'?'sun':'moon')}</button></div></header><main class="content" id="main-content">`}
function labelForView(){return ({dashboard:'Command Center',course:'Core Course',positions:'Position Academy',position:'Position Academy',lesson:'Lesson',designer:'Play Designer',simulator:'Coach Simulator',film:'Film Room',progress:'My Progress',settings:'Settings'})[model.view]||'Dashboard'}
function footer(){return `<footer class="footer"><span>FOOTBALL ACADEMY · VERSION 1.0 · FOOTBALL IQ, NOT PHYSICAL TRAINING</span><span>Progress stays on this device unless you export a backup.</span></footer></main></div></div>`}
function badge(s,cls=''){return `<span class="chip ${cls}">${s}</span>`}
function titleBlock(tag,title,description){return `<div class="page-head"><div class="eyebrow">${E(tag)}</div><h1>${E(title)}</h1><p class="lead">${E(description)}</p></div>`}
function statBox(label,value,ico){return `<div class="card stat-card"><div class="stat-icon">${icon(ico)}</div><div class="stat"><div class="stat-num">${value}</div><div class="label">${E(label)}</div></div></div>`}
function featureButton(label,view,ico){return `<button class="btn secondary" data-go="${view}">${icon(ico)} ${E(label)}</button>`}

function practiceLevel(){return ['rookie','starter','allpro'].includes(person()?.practiceLevel)?person().practiceLevel:'rookie'}
function practiceChooser(){const active=practiceLevel();const descriptions={rookie:'Rookie: full coaching tips, forgiving outcomes, and guided reads.',starter:'Starter: fewer hints and more realistic decisions.',allpro:'All-Pro: minimal pre-play hints, tighter execution, and tougher reads.'};return `<div class="card pad mb-md"><div class="between wrap"><div><div class="caps">Practice & mastery · Difficulty</div><p class="muted small mt-sm" style="max-width:55ch">${E(descriptions[active])}</p></div><div class="tabstrip" role="group" aria-label="Practice difficulty">${[['rookie','Rookie'],['starter','Starter'],['allpro','All-Pro']].map(([id,label])=>`<button class="tab ${id===active?'active':''}" data-practice-level="${id}" aria-pressed="${id===active}">${label}</button>`).join('')}</div></div></div>`}

function dashboard(){const p=person(),next=nextLesson();const c=completedCount(coreLessons),ps=completedCount(positionLessons);
 return `${titleBlock('Welcome to the field',`Your playbook starts here, ${p?.name||'Rookie'}.`,'Learn the game from first principles, then build the football IQ to read formations, understand the strategy, and call the right play.')}
 <div class="card hero"><div><div class="eyebrow">${done('core-6')?'THE FIELD IS OPEN':'ROOKIE TRAINING IN PROGRESS'}</div><h1>${done('core-6')?'Ready for the next challenge?':'Start thinking like a football player.'}</h1><p class="hero-description">Short interactive lessons. Real choices. Zero physical drills. Work through the fundamentals and unlock positions, playbooks, and advanced game scenarios.</p><button class="btn" data-lesson="${E(next.id)}">${icon('play')} ${done('core-1')?'Continue learning':'Begin Level 1'} ${icon('arrow')}</button><div class="hero-callout">${icon('shield')} All lesson progress is stored privately in this browser.</div></div><div class="hero-graphic" aria-hidden="true">${heroArt()}</div></div>
 <div class="grid cols-4 stats-grid mt-md">${statBox('Core lessons',`${c} / ${coreLessons.length}`,'book')}${statBox('Position tiers',`${ps} / 30`,'users')}${statBox('Total lessons',`${completion()} / ${ALL.length}`,'check')}${statBox('Knowledge XP',points(),'trophy')}</div>
 <div class="grid cols-2 mt-lg"><div class="card pad"><div class="between"><h3>Recommended next step</h3>${badge('YOUR PATH','success')}</div><h2 class="mt-md">${E(next.title)}</h2><p class="lead small">${E(next.summary)}</p><div class="between mt-md"><span class="tiny">${next.duration} MIN · KNOWLEDGE LESSON</span><button class="btn small" data-lesson="${next.id}">Continue ${icon('arrow')}</button></div></div><div class="card pad"><div class="between"><h3>Foundation mastery</h3><strong>${pct(completedCount(fundamentals),6)}%</strong></div><div class="progress-track mt-md"><div class="progress-fill" style="width:${pct(completedCount(fundamentals),6)}%"></div></div><p class="lead small">Complete all six foundations to unlock position-specialist learning.</p><div class="between mt-md">${badge(done('core-6')?'SPECIALIZATION UNLOCKED':'COMPLETE THE BASICS',done('core-6')?'success':'warn')}<button class="btn ghost small" data-go="course">View course</button></div></div></div>
 <div class="section-head"><div><div class="caps">Explore and apply</div><h2>Get on the field</h2></div></div><div class="grid cols-3">${dashboardTile('Play Designer','Watch routes and formations unfold, one phase at a time.','designer','strategy')}${dashboardTile('Coach Simulator','Call plays through a live drive or tackle situational challenges.','simulator','play')}${dashboardTile('Film Room','Study short play sequences and identify what the defense is doing.','film','film')}</div>
 <div class="section-head"><h2>Upcoming core lessons</h2><button class="btn ghost small" data-go="course">Full syllabus ${icon('arrow')}</button></div><div class="card">${coreLessons.filter(l=>!done(l.id)).slice(0,3).map(l=>courseRow(l)).join('')||'<div class="empty">All core lessons complete. Specialist paths are ready.</div>'}</div>`;
}
function heroArt(){return `<svg viewBox="0 0 420 230" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="heroShade" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#345d48"/><stop offset="1" stop-color="#153428"/></linearGradient></defs><g transform="translate(5 6) rotate(-8 210 110)"><rect x="22" y="18" width="380" height="204" rx="15" fill="url(#heroShade)" stroke="#53755f" stroke-width="2"/>${[90,164,238,312].map(x=>`<path d="M${x} 20v200" stroke="#83a98b" stroke-width="1.3" opacity=".55"/>`).join('')}<path d="M40 119h346" stroke="#9ac6a5" stroke-width="2" stroke-dasharray="7 7"/><g stroke="#a7e890" stroke-width="4" stroke-linecap="round" fill="none"><path d="M101 176Q143 138 172 77"/><path d="M318 172Q276 133 249 69"/><path d="M208 175V91"/></g>${[[100,178,'X'],[208,178,'QB'],[318,178,'Z'],[168,77,'S'],[252,72,'S']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="19" fill="${t==='S'?'#ed9979':'#a5e5c0'}" stroke="#1b3127" stroke-width="3"/><text x="${x}" y="${y+5}" text-anchor="middle" font-weight="900" fill="#1d4130" font-size="12">${t}</text>`).join('')}</g></svg>`}
function dashboardTile(title,description,view,ico){return `<div class="card pad hoverable"><div class="path-icon">${icon(ico)}</div><h3 class="mt-md">${E(title)}</h3><p class="muted small mt-sm" style="min-height:49px">${E(description)}</p><button class="btn ghost small mt-md" data-go="${view}">Explore ${icon('arrow')}</button></div>`}
function courseRow(l){const complete=done(l.id),locked=!isUnlocked(l);const sc=person()?.completed?.[l.id];return `<div class="course-item ${complete?'done':''}"><div class="number-tile">${complete?icon('check'):String(l.number||'★').padStart(2,'0')}</div><div style="flex:1;min-width:0"><div class="caps">${E(l.category)} · ${l.duration} min</div><h3>${E(l.title)}</h3><p>${E(l.summary)}</p><div class="meta">${badge(complete?`Mastered · ${sc.best}%`:locked?'Locked':'Available',complete?'success':locked?'':'info')}${badge(`${questionBankFor(l).length} questions in bank · 5 randomly drawn`)}</div></div><div class="action"><button class="btn ${complete?'ghost':'secondary'} small" ${locked?'disabled aria-label="Lesson locked"':''} data-lesson="${E(l.id)}">${locked?icon('lock'):complete?icon('refresh'):icon('play')} ${locked?'Locked':complete?'Review':'Start'}</button></div></div>`}
function course(){const foundationDone=completedCount(fundamentals);return `${titleBlock('The core curriculum','Learn the complete game','Twenty connected levels progress from first-down fundamentals to college-style reads, match coverage, run/pass structures and full-game planning. Each checkpoint draws five different questions from a lesson bank; earn 80% to advance.')}
 <div class="grid cols-2 mb-md">${progressSummary('Levels 1–6 · Foundations',foundationDone,6,'Unlock position specializations')}${progressSummary('Levels 7–10 · Football IQ',completedCount(advancedCore),4,'Unlock advanced electives')}${progressSummary('Levels 11–20 · College Concepts',completedCount(collegeCore),collegeCore.length,'Study real reads and game structure')}</div><div class="section-head"><div><div class="caps">Stage 01</div><h2>Football fundamentals</h2></div>${badge(`${foundationDone}/${fundamentals.length} mastered`)}</div><div class="card">${fundamentals.map(courseRow).join('')}</div><div class="section-head"><div><div class="caps">Stage 02</div><h2>Football intelligence</h2></div>${badge(`${completedCount(advancedCore)}/${advancedCore.length} mastered`)}</div><div class="card">${advancedCore.map(courseRow).join('')}</div><div class="section-head"><div><div class="caps">Stage 03</div><h2>College scheme, reads & game planning</h2></div>${badge(`${completedCount(collegeCore)}/${collegeCore.length} mastered`)}</div><div class="card">${collegeCore.map(courseRow).join('')}</div><div class="section-head"><div><div class="caps">Optional</div><h2>Advanced electives</h2></div>${badge(done('core-10')?'Unlocked':'Unlock after Level 10',done('core-10')?'success':'warn')}</div><div class="card">${electiveLessons.map(l=>courseRow({...l,number:'★'})).join('')}</div>`}
function progressSummary(name,n,total,sub){return `<div class="card pad"><div class="between"><strong>${E(name)}</strong><span class="muted small">${n} / ${total}</span></div><div class="progress-track mt-md"><div class="progress-fill" style="width:${pct(n,total)}%"></div></div><div class="tiny mt-sm">${E(sub)}</div></div>`}
function positionsScreen(){const visible=positions.filter(p=>model.filter==='All'||p.unit===model.filter);const unlocked=done('core-6');return `${titleBlock('Choose your specialization','Position Academy','Every position has three independent tiers: Rookie, Starter, and All-Pro. Learn the assignments, then learn to read the opponent and react intelligently.')}${unlocked?'<div class="info-banner"><strong>Specializations unlocked.</strong> Choose any position. Finish Rookie to unlock Starter, and Starter to unlock All-Pro.</div>':'<div class="locked-banner">'+icon('lock')+' Complete Core Levels 1–6 to unlock the specialist courses. You can explore the available paths below.</div>'}<div class="section-head"><h2>Choose a position</h2><div class="tabstrip">${['All','Offense','Defense','Special Teams'].map(f=>`<button class="tab ${model.filter===f?'active':''}" data-filter="${E(f)}">${E(f)}</button>`).join('')}</div></div><div class="grid cols-3">${visible.map(p=>{const d=[1,2,3].filter(t=>done(`pos-${p.id}-${t}`)).length;return `<div class="card path-card ${unlocked?'':'locked'}"><div class="path-head"><div class="path-icon" style="font-weight:900;font-size:.9rem">${E(p.abbr)}</div>${badge(`${d}/3 tiers`,d===3?'success':'')}</div><h3>${E(p.name)}</h3><p>${E(p.description)}</p><div class="progress-track"><div class="progress-fill" style="width:${d/3*100}%"></div></div><button class="btn ${unlocked?'secondary':'ghost'} small full" data-position="${p.id}">Explore path ${icon('arrow')}</button></div>`}).join('')}</div>`}
function positionScreen(){const p=positions.find(x=>x.id===model.positionId)||positions[0];const lessons=positionLessons.filter(l=>l.positionId===p.id);return `<div class="page-head"><button class="btn ghost small" data-go="positions">${icon('left')} All positions</button></div><div class="card position-hero"><div class="between"><div><div class="eyebrow">${E(p.unit)} · POSITION PATH</div><h1>${E(p.name)}</h1><p class="lead">${E(p.description)}</p></div><div class="number-tile" style="width:72px;height:72px;font-size:1.4rem;color:var(--lime)">${E(p.abbr)}</div></div></div><div class="section-head"><div><div class="caps">From rookie to all-pro</div><h2>Your specialization</h2></div></div><div class="card">${lessons.map((l,i)=>{const tier=['Rookie','Starter','All-Pro'][i];return courseRow({...l,number:i+1,category:tier+' tier'})}).join('')}</div><div class="coach-note mt-md"><strong>${icon('info')} How unlocking works</strong><p>After the six foundation levels, Rookie opens for every position. Completing a tier with at least 80% unlocks the next tier for that position only. You can learn several positions at the same time.</p></div>`}
function lessonScreen(){const l=byId[model.lessonId];if(!l)return course();const qi=model.quiz;const concept=l.concepts[model.concept];const coaching=coachingFor(l,model.concept);return `<div class="page-head"><button class="btn ghost small" data-action="lesson-back">${icon('left')} ${l.positionId?'Position path':l.id.startsWith('elect-')?'Advanced electives':'Core course'}</button></div><div class="eyebrow">${E(l.category)} · ${l.duration} MIN</div><h1>${E(l.title)}</h1><p class="lead">${E(l.summary)}</p><div class="grid lesson-layout mt-lg"><div class="card lesson-panel">${qi?quizPanel(l):`<div class="between mb-md"><span class="caps">Learning guide</span>${badge(`CONCEPT ${model.concept+1} OF ${l.concepts.length}`,'info')}</div><div class="step-dots">${l.concepts.map((_,i)=>`<span class="dot ${i===model.concept?'active':i<model.concept?'done':''}"></span>`).join('')}</div><div class="concept-index">FIELD GUIDE / ${String(model.concept+1).padStart(2,'0')}</div><h2>${E(concept[0])}</h2><p class="concept-body">${E(concept[1])}</p><div class="example"><strong style="color:var(--text)">On-field example</strong><br>${E(concept[2]||'Watch how this changes the decisions made after the snap.')}</div><div class="coach-note concept-coaching"><strong>${icon('target')} Why this matters</strong><p>${E(coaching.insight)}</p></div>${l.id==='core-20'&&model.concept===1?fullPlayTeachingCard():''}<div class="between mt-lg"><button class="btn ghost" data-action="previous-concept" ${model.concept===0?'disabled':''}>${icon('left')} Previous</button><button class="btn" data-action="next-concept">${model.concept===l.concepts.length-1?'Start checkpoint':'Next concept'} ${icon('arrow')}</button></div>`}</div><aside class="card pad lesson-sidebar"><div class="caps">Lesson objectives</div><ul class="goals-list mt-md">${l.goals.map(g=>`<li>${icon('check')}<span>${E(g)}</span></li>`).join('')}</ul><div class="keyline"></div><div class="caps">Your progress</div>${done(l.id)?`<div class="mt-sm">${badge('Mastered','success')} ${badge(`${person().completed[l.id].best}% best score`)}</div>`:'<div class="muted small mt-sm">Pass the knowledge checkpoint at 80% or higher to master this lesson.</div>'}<div class="keyline"></div><div class="coach-note"><strong>${icon('target')} What to watch for</strong><p>${E(coaching.watch)}</p></div><button class="btn ghost small full mt-md" data-go="designer">${icon('field')} Explore the play diagram</button></aside></div>`}
function quizPanel(l){const q=model.quiz;const qs=q.questions;if(q.submitted){const score=q.score;const pass=score>=80;return `<div class="caps">Checkpoint results</div><div class="between mt-md"><div><div class="score-number">${score}%</div><h2 class="mt-sm">${pass?'Mastery achieved':'Review and try again'}</h2><p class="muted small mt-sm">${qs.filter((item,i)=>Number(q.answers[i])===Number(item[2])).length} correct out of ${qs.length}. ${pass?'You have unlocked the next eligible lesson.':'Each checkpoint has five randomly chosen questions; 80% (four of five) is required for mastery.'}</p></div><div class="stat-icon" style="width:65px;height:65px">${icon(pass?'trophy':'refresh')}</div></div><div class="mt-lg">${qs.map((z,i)=>{let right=Number(q.answers[i])===Number(z[2]);return `<div class="answer-review ${right?'':'wrong'}"><strong>${right?'✓':'✕'} ${E(z[0])}</strong><p>Your answer: ${E(z[1][q.answers[i]])}. ${!right?`Correct answer: ${E(z[1][Number(z[2])])}. `:''}${E(z[3])}</p></div>`}).join('')}</div><div class="flex wrap mt-lg"><button class="btn secondary" data-action="restart-quiz">${icon('refresh')} Retry checkpoint</button><button class="btn" data-action="lesson-back">${icon('arrow')} ${pass?'Continue course':'Back to lessons'}</button></div>`}
 const i=q.index;const item=qs[i];return `<div class="between"><div class="caps">Knowledge checkpoint</div>${badge(`Question ${i+1} / ${qs.length}`,'info')}</div><div class="step-dots mt-md">${qs.map((_,n)=>`<span class="dot ${n===i?'active':q.answers[n]!==null&&q.answers[n]!==undefined?'done':''}"></span>`).join('')}</div><h2 class="quiz-question">${E(item[0])}</h2><div class="quiz-grid">${item[1].map((a,n)=>`<button class="quiz-option ${q.answers[i]===n?'selected':''}" data-answer="${n}" aria-pressed="${q.answers[i]===n}"><span class="quiz-letter">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[n]}</span><span>${E(a)}</span></button>`).join('')}</div><div class="between mt-lg"><button class="btn ghost" data-action="previous-question" ${i===0?'disabled':''}>${icon('left')} Previous</button><button class="btn" data-action="next-question" ${q.answers[i]===undefined||q.answers[i]===null?'disabled':''}>${i===qs.length-1?'Grade checkpoint':'Next question'} ${icon('arrow')}</button></div><div class="tiny mt-md">Answers are graded after all questions are complete. Feedback explains every correct answer.</div>`}
function designer(){const level=practiceLevel();const play=playOptions.find(p=>p.id===model.playId),def=defenses.find(d=>d.id===model.defenseId);const info={QB:'The quarterback reads the defense and makes the handoff or passing decision.',X:'Outside receiver. Routes can attack vertical space or create inside leverage.',H:'Slot receiver. Often attacks space between linebackers and safeties.',Y:'Tight end. Can block or release into a passing route.',Z:'Outside receiver. Helps stretch or attack the coverage.',OL:'The offensive line protects the pocket and coordinates the running scheme.',RB:'Running back. Carries the ball, catches screens, and may pass protect.',DL:'Defensive linemen control gaps and rush the passer.',S:'Safeties provide coverage help and defend deep throws.',C:'Cornerbacks defend outside receivers and passing space.'};return `${titleBlock('Interactive chalkboard','Play Designer','Choose a play and defensive look, then step through the action. These simplified diagrams teach concepts rather than representing a complete team-specific playbook.')}
 ${practiceChooser()}<div class="grid cols-2 mb-md"><div class="card pad"><label class="label-field" for="play-select">Offensive play</label><select class="select" id="play-select" data-select="play">${playOptions.map(p=>`<option value="${p.id}" ${p.id===model.playId?'selected':''}>${E(p.name)} · ${p.type}</option>`).join('')}</select></div><div class="card pad"><label class="label-field" for="defense-select">Defensive look</label><select class="select" id="defense-select" data-select="defense">${defenses.map(d=>`<option value="${d.id}" ${d.id===model.defenseId?'selected':''}>${E(d.name)}</option>`).join('')}</select></div></div>
 <div class="grid" style="grid-template-columns:minmax(0,1fr)"><div class="card pad"><div class="between mb-md"><div><h3>${E(play.name)}</h3><div class="muted small">${level==='allpro'&&model.playStep<3?'Analyze the play before revealing the coaching answer.':E(play.summary)}</div></div>${badge(play.type==='Pass'?'PASS':'RUN','info')}</div>${playDiagram(model.playId,model.defenseId,model.playStep,model.playHighlight)}<div class="play-controls"><button class="btn secondary small" data-action="play-step-back" ${model.playStep===0?'disabled':''}>${icon('left')} Back</button><button class="btn small" data-action="play-step-next">${icon('play')} ${model.playStep===3?'Replay':'Next phase'} ${icon('arrow')}</button><button class="btn ghost small" data-action="play-reset">${icon('refresh')} Reset</button>${badge(['Pre-snap','The snap','Play develops','The read'][model.playStep],'success')}</div><div class="coach-note"><strong>${['Pre-snap setup','The snap','Play development','Quarterback or runner decision'][model.playStep]}</strong><p>${E(level==='rookie'?[`Notice the ${def.name.toLowerCase()} defense. ${def.description}`,`The ball is snapped. The offense begins ${play.type==='Pass'?'its route concepts':'its blocking and run'} assignments.`,play.summary,play.effect][model.playStep]:level==='starter'&&model.playStep<3?`Look at the ${def.name.toLowerCase()} alignment. ${model.playStep<2?'Predict the likely movement and the read.':play.read}`:level==='allpro'&&model.playStep<3?`Before advancing, identify the likely threat and each player's responsibility. ${model.playStep===2?`Focus on: ${play.read}.`:''}`:play.effect)}</p></div></div></div>
 <div class="section-head"><h2>Inspect the players</h2>${badge('SELECT A ROLE')}</div><div class="card pad"><div class="tabstrip">${['QB','RB','OL','X','H','Y','Z','DL','S','C'].map(r=>`<button class="tab ${model.playHighlight===r?'active':''}" data-role="${r}">${r}</button>`).join('')}</div><div class="coach-note mt-md"><strong>${E(model.playHighlight||'Select a player role')}</strong><p>${E(info[model.playHighlight]||`Look for the highlighted role on the diagram. The yellow paths show the planned movement. ${play.read}.`)}</p></div></div>`}
const filmChallenges={
 motion:{starter:['What additional evidence should confirm a possible man-coverage indicator?',['Defender reactions after the snap','The sideline color','A referee signal'],0,'Motion gives a clue, but post-snap assignments provide stronger evidence.'],allpro:['A defender travels with motion, but the secondary rotates at the snap. What should the QB do?',['Assume man coverage is certain','Confirm coverage from post-snap movement','Ignore the secondary entirely'],1,'A defense can disguise coverage. The quarterback checks the actual rotation after the snap.']},
 highlow:{starter:['How does a flood concept stress a zone defender?',['Force a choice between routes at different depths','Move every defender to the far hash','Require all receivers to run vertically'],0,'A flood stacks routes at different levels and tests the underneath/flat defenders.'],allpro:['The flat defender widens with the short route. What is the quarterback reading next?',['A throwing window behind that defender','The referee for a penalty','Whether the center can catch a pass'],0,'The defender leaving the intermediate window can open a route behind him if the deep defender does not close it.']},
 pressure:{starter:['Why can a screen work against an aggressive rush?',['Use the space behind committed rushers','Prevent any defender from moving','Automatically stop the game clock'],0,'The offense lets rushers advance, then throws into space with blockers arriving.'],allpro:['A linebacker stays home while the other defenders blitz. What changes about the screen?',['It may be diagnosed and disrupted','It guarantees a large gain','The offensive line no longer blocks'],0,'A defender who recognizes the screen and stays back can undercut the pass or tackle the back quickly.']}
};
function filmScreen(){const f=filmCases.find(x=>x.id===model.filmId)||filmCases[0];const level=practiceLevel();const challenge=level==='rookie'?[f.question,f.answers,f.correct,f.why]:filmChallenges[f.id][level];const reveal=level==='rookie'||(level==='starter'&&model.filmStep>=2)||model.filmAnswer!==null;return `${titleBlock('Watch, recognize, decide','Film Room','Study a fictional play in four stages. Difficulty changes the available coaching hints and the football reads required.')}
 ${practiceChooser()}<div class="tabstrip mb-md">${filmCases.map(c=>`<button class="tab ${c.id===f.id?'active':''}" data-film="${c.id}">${E(c.name)}</button>`).join('')}</div><div class="grid lesson-layout"><div class="card pad"><div class="between mb-md"><h3>${E(f.type)}</h3>${badge(`FRAME ${model.filmStep+1} / 4`,'info')}</div>${playDiagram(f.play,f.defense,model.filmStep)}<div class="play-controls"><button class="btn ghost small" data-action="film-back" ${model.filmStep===0?'disabled':''}>${icon('left')} Rewind</button><button class="btn secondary small" data-action="film-next" ${model.filmStep===3?'disabled':''}>${icon('play')} Next frame</button><button class="btn ghost small" data-action="film-reset">${icon('refresh')} Restart</button></div><div class="coach-note"><strong>${E(f.frames[model.filmStep][0])}</strong><p>${reveal?E(f.frames[model.filmStep][1]):level==='starter'?'Observe the alignment and movement. Coaching explanation unlocks at frame three.':'All-Pro film study: make your read first. Coaching breakdown appears after you answer.'}</p></div></div><div class="card pad lesson-sidebar"><div class="caps">${level==='rookie'?'Guided recognition':level==='starter'?'Recognition challenge':'All-Pro film breakdown'}</div><h3 class="mt-md">${E(challenge[0])}</h3><div class="quiz-grid mt-md">${challenge[1].map((ans,i)=>`<button class="quiz-option ${model.filmAnswer===i?'selected':''}" data-film-answer="${i}" aria-pressed="${model.filmAnswer===i}"><span class="quiz-letter">${'ABC'[i]}</span><span>${E(ans)}</span></button>`).join('')}</div>${model.filmAnswer!==null?`<div class="feedback ${model.filmAnswer===challenge[2]?'good':''}"><strong>${model.filmAnswer===challenge[2]?'Sound read':'Revisit the coverage'}</strong><p>${E(challenge[3])}</p><p class="mt-sm">${E(f.why)}</p></div>`:`<p class="muted small mt-md">${level==='rookie'?'Use the frame notes for guidance.':level==='starter'?'Review the action before answering.':'Make your decision before the coaching breakdown appears.'}</p>`}</div></div>`}
function newSim(challenge='drive'){
 const conf={drive:{position:50,target:60,down:1,clock:102,timeouts:2,offense:14,defense:17,message:'You have the ball at midfield, down by three. There is 1:42 left in the fourth quarter.'},thirdshort:{position:64,target:66,down:3,clock:130,timeouts:2,offense:14,defense:17,message:'3rd & 2 at the opponent 36. Choose a play that can earn the first down.'},thirdlong:{position:50,target:64,down:3,clock:130,timeouts:2,offense:14,defense:17,message:'3rd & 14 near midfield. A conversion needs a play beyond the marker.'},redzone:{position:88,target:94,down:2,clock:102,timeouts:2,offense:14,defense:17,message:'2nd & 6 at the opponent 12. The defense crowds the middle of the field.'},clock:{position:50,target:60,down:1,clock:70,timeouts:0,offense:13,defense:17,message:'Down by four at midfield with 1:10 left and no timeouts. You need a touchdown.'}};
 const c=conf[challenge]||conf.drive;return {...c,challenge:conf[challenge]?challenge:'drive',plays:0,over:false,log:[c.message],seed:3};
}
function simReason(challenge,type){
 const z=situations.find(x=>x.id===challenge);if(!z)return ({run:'A run can gain reliable yards, but an inbounds tackle keeps the clock running.',short:'A quick pass helps move the chains. Check whether the gain reaches the marker.',intermediate:'An intermediate route aims near or beyond the sticks with greater risk than a quick pass.',out:'Getting out of bounds can preserve crucial time late in the game, depending on the clock rules.',deep:'Deep throws trade completion probability for the chance of a large gain.'})[type];
 const mapping={thirdshort:{run:0,short:1,intermediate:1,out:1,deep:2},thirdlong:{run:0,short:0,intermediate:1,out:0,deep:1},redzone:{run:0,short:1,intermediate:1,out:1,deep:1},clock:{run:2,short:0,intermediate:0,out:1,deep:0}};
 const n=mapping[challenge]?.[type];return n===undefined?'Consider field position, clock, and defensive alignment.':z.feedback[n][1];
}
function simPlay(type){const s=model.sim;if(!s||s.over)return;const difficulty=practiceLevel();const n=s.plays+1;const mod=(n*7+s.seed+(type==='deep'?3:type==='out'?7:type==='intermediate'?5:0))%10;
 let gain=0,elapsed=0,complete=true,label='';
 if(type==='run'){gain=(difficulty==='rookie'?3:difficulty==='starter'?2:1)+(mod%5);elapsed=31;label=`Inside run gains ${gain} yards.`}
 if(type==='short'){complete=difficulty==='rookie'?mod!==1:difficulty==='starter'?mod!==1&&mod!==5:mod!==1&&mod!==4&&mod!==5;gain=complete?5+(mod%7):0;elapsed=complete?18:6;label=complete?`Short pass completed for ${gain} yards.`:'Short pass incomplete.'}
 if(type==='intermediate'){complete=difficulty==='rookie'?mod!==2&&mod!==5:difficulty==='starter'?mod!==2&&mod!==5&&mod!==8:mod===1||mod===3||mod===6||mod===9;gain=complete?10+(mod%9):0;elapsed=complete?19:7;label=complete?`Intermediate pass completed for ${gain} yards.`:'Intermediate pass incomplete.'}
 if(type==='out'){complete=difficulty==='rookie'?mod!==2:difficulty==='starter'?mod!==2&&mod!==7:mod!==2&&mod!==5&&mod!==7;gain=complete?7+(mod%5):0;elapsed=complete?9:6;label=complete?`Sideline completion for ${gain}; the receiver gets out of bounds.`:'Sideline pass incomplete.'}
 if(type==='deep'){complete=difficulty==='rookie'?[2,3,6,8].includes(mod):difficulty==='starter'?[3,6,8].includes(mod):[3,8].includes(mod);gain=complete?20+(mod%9):0;elapsed=complete?16:8;label=complete?`Deep pass completed for ${gain}!`:'Deep pass falls incomplete.'}
 if(!['run','short','intermediate','out','deep'].includes(type))return;
 s.plays++;s.clock=Math.max(0,s.clock-elapsed);s.position=clamp(s.position+gain,0,100);s.message=label;
 if(s.position>=100){s.offense+=6;s.over=true;s.message+=` TOUCHDOWN! Six points added; the simulation ends before the conversion try.`}
 else if(s.position>=s.target){s.down=1;s.target=Math.min(100,s.position+10);s.message+=' FIRST DOWN! The chains reset.'}
 else if(s.down===4){s.over=true;s.message+=' Turnover on downs. The defense takes over.'}
 else s.down++;
 if(s.clock===0&&!s.over){s.over=true;s.message+=' The clock reaches 0:00.'}
 const advice=simReason(s.challenge,type);s.message+=` Coaching: ${advice}`;s.log.unshift(s.message);render();
}
function simKick(){const s=model.sim;if(!s||s.over)return;const distance=Math.round(100-s.position+17);if(distance>60){notify('That field-goal attempt is beyond the simplified simulator’s range.');return}const level=practiceLevel();const sure=level==='rookie'?47:level==='starter'?43:37;const made=distance<=sure||((s.plays+s.seed)%4!==0&&distance<=55);s.clock=Math.max(0,s.clock-5);s.plays++;s.over=true;if(made){s.offense+=3;s.message=`The ${distance}-yard field goal is GOOD! Final score ${s.offense}–${s.defense}. ${s.offense===s.defense?'The game is tied.':'The score has changed.'}`}else s.message=`The ${distance}-yard field goal MISSES. The defense takes over.`;s.log.unshift(s.message);render()}
function simulatorScreen(){const s=model.sim||(model.sim=newSim());const level=practiceLevel();const situation=situations.find(x=>x.id===s.challenge);const tips={rookie:'Use the coaches’ explanations to match the call to the down, distance and clock.',starter:'Read the situation, estimate the risk and select a concept. Results may not go your way.',allpro:'Minimal hints. Manage downs, yards and the clock without pre-play advice.'};const choices=[['run','Inside Run','Steady yards · clock runs'],['short','Short Pass','Quick throw · lower risk'],['intermediate','Intermediate Pass','Targets the sticks · moderate risk'],['out','Sideline Pass','Can preserve time'],['deep','Deep Pass','Large gain · low completion chance']];return `${titleBlock('Live drive + situational challenges','Coach Simulator','The Situation Lab is now part of this simulator. Select a game situation, call plays, manage time, and study how each decision changes the result.')}
 ${practiceChooser()}<div class="card pad mb-md"><div class="caps mb-md">Choose your game situation</div><div class="tabstrip" role="group" aria-label="Game situations">${[['drive','Final Drive'],...situations.map(z=>[z.id,z.name])].map(([id,label])=>`<button class="tab ${s.challenge===id?'active':''}" data-sim-situation="${id}" aria-pressed="${s.challenge===id}">${E(label)}</button>`).join('')}</div>${situation?`<div class="coach-note mt-md"><strong>${E(situation.state)}</strong><p>${E(situation.question)}</p></div>`:''}</div>
 <div class="grid cols-2"><div class="card pad"><div class="caps">Fourth quarter</div><div class="sim-score mt-sm"><span>YOUR TEAM</span>${s.offense} : ${s.defense}<span>OPPONENT</span></div><div class="sim-clock"><div class="stat"><span class="caps">Game clock</span><strong class="stat-num">${Math.floor(s.clock/60)}:${String(s.clock%60).padStart(2,'0')}</strong></div><div class="stat"><span class="caps">Down & distance</span><strong class="stat-num">${s.over?'Final':`${['','1st','2nd','3rd','4th'][s.down]} & ${s.target===100?'Goal':s.target-s.position}`}</strong></div><div class="stat"><span class="caps">Timeouts</span><strong class="stat-num">${s.timeouts}</strong></div></div>${driveField(s.position,s.target)}<div class="flex mt-sm wrap">${badge(`BALL: ${s.position<=50?'OWN '+s.position:'OPP '+(100-s.position)}`,'info')}${badge('Blue = ball · Gold = marker')}</div><div class="feedback ${s.over?'good':''}"><strong>${s.over?'Drive complete':'Coach’s report'}</strong><p>${E(s.message)}</p></div><button class="btn ghost small mt-md" data-action="sim-reset">${icon('refresh')} Restart this situation</button></div>
 <div class="card pad"><div class="caps">Call your next play · ${level==='allpro'?'All-Pro':level==='starter'?'Starter':'Rookie'}</div>${s.over?`<h2 class="mt-md">${s.offense>s.defense?'You won!':s.offense===s.defense?'The game is tied':'The defense holds.'}</h2><p class="lead">Restart to test a different strategy.</p><button class="btn mt-md" data-action="sim-reset">Play again ${icon('arrow')}</button>`:`<h2 class="mt-md">Choose a strategy</h2><p class="muted small mt-sm">${E(tips[level])}</p><div class="grid cols-2 mt-md">${choices.map(([id,label,detail])=>`<button class="sim-btn" data-sim-play="${id}"><span>${E(label)}</span>${level==='rookie'?`<small>${E(detail)}</small>`:level==='starter'&&['run','deep'].includes(id)?`<small>${E(detail)}</small>`:''}</button>`).join('')}</div><div class="flex wrap mt-md"><button class="btn secondary small" data-action="sim-timeout" ${s.timeouts<1?'disabled':''}>${icon('clock')} Take timeout (${s.timeouts})</button>${s.position>=60?`<button class="btn secondary small" data-action="sim-kick">${icon('flag')} Kick field goal (~${Math.round(100-s.position+17)} yd)</button>`:''}</div>`}<div class="keyline"></div><div class="caps">Play-by-play log</div><ul class="message-log mt-sm">${s.log.map(x=>`<li>${E(x)}</li>`).join('')}</ul></div></div>`}
function progressScreen(){const p=person();const groups=[['Fundamentals',fundamentals],['Advanced Core',advancedCore],['Position Academy',positionLessons],['Strategy Electives',electiveLessons]];const attempts=Object.values(p.completed).reduce((v,x)=>v+(x.attempts||0),0);return `${titleBlock('Your learning record','My Progress','See your mastery and checkpoint history. Every score measures knowledge, not physical playing ability.')}
 <div class="grid cols-4 stats-grid">${statBox('Lessons mastered',completion(),'check')}${statBox('Checkpoint attempts',attempts,'clipboard')}${statBox('Total XP',points(),'star')}${statBox('Course completion',pct(completion(),ALL.length)+'%','chart')}</div><div class="grid cols-2 mt-lg"><div class="card pad"><h3>Curriculum progress</h3><div class="bar-stack mt-md">${groups.map(([name,a])=>`<div><div class="progress-line"><strong>${E(name)}</strong><span>${completedCount(a)} / ${a.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct(completedCount(a),a.length)}%"></div></div></div>`).join('')}</div></div><div class="card pad"><h3>Achievements</h3><div class="stack mt-md">${[['First Snap','Complete Level 1',done('core-1')],['Football Fan','Complete all six foundation levels',done('core-6')],['Football Thinker','Complete the ten core levels',done('core-10')],['Position Specialist','Reach All-Pro in one position',positions.some(x=>done(`pos-${x.id}-3`))],['Complete Football IQ','Master every available lesson',completion()===ALL.length]].map(([n,desc,yes])=>`<div class="between" style="padding:8px 0;border-bottom:1px solid var(--line)"><div class="flex"><div class="stat-icon">${icon(yes?'trophy':'lock')}</div><div><strong>${E(n)}</strong><div class="tiny">${E(desc)}</div></div></div>${badge(yes?'Earned':'Locked',yes?'success':'')}</div>`).join('')}</div></div></div>
 <div class="section-head"><h2>Recent mastery</h2></div><div class="card">${Object.entries(p.completed).filter(([id,v])=>v.passed&&byId[id]).sort((a,b)=>String(b[1].last).localeCompare(String(a[1].last))).slice(0,12).map(([id,v])=>`<div class="course-item done"><div class="number-tile">${icon('check')}</div><div style="flex:1"><h3>${E(byId[id].title)}</h3><p>Best score: ${v.best}% · Attempts: ${v.attempts}</p></div><div class="action"><button class="btn ghost small" data-lesson="${E(id)}">Review</button></div></div>`).join('')||'<div class="empty">Your first completed lesson will appear here.</div>'}</div>`}
function settingsScreen(){const p=person();return `${titleBlock('Your academy, your settings','Settings','Manage your student name, display theme, profiles, and backups. Nothing here requires an account or sends your name to GitHub.')}
 <div class="grid cols-2"><div class="card pad"><h3>Student profile</h3><p class="muted small mt-sm">This is the name displayed on the dashboard. It stays in this browser.</p><form data-form="rename" class="stack mt-md"><label for="rename" class="label-field">Student name</label><input class="input" id="rename" name="name" value="${E(p.name)}" maxlength="40" minlength="1" required autocomplete="nickname"><button type="submit" class="btn">${icon('check')} Save name</button></form><div class="keyline"></div><h3>Switch student</h3><div class="stack mt-sm">${db.profiles.map(x=>`<button class="quiz-option ${x.id===db.activeId?'selected':''}" data-switch="${E(x.id)}"><span class="avatar">${E(x.name.slice(0,1).toUpperCase())}</span><span>${E(x.name)} ${x.id===db.activeId?'· Current':''}</span></button>`).join('')}</div><button class="btn ghost small mt-md" data-action="add-profile">${icon('plus')} Add another student</button></div>
 <div class="stack"><div class="card pad"><h3>Appearance</h3><p class="muted small mt-sm">Dark mode is the default. Change the theme at any time.</p><div class="tabstrip mt-md"><button class="tab ${db.theme==='dark'?'active':''}" data-theme="dark">${icon('moon')} Dark</button><button class="tab ${db.theme==='light'?'active':''}" data-theme="light">${icon('sun')} Light</button></div><div class="keyline"></div><h3>Install as an app</h3><p class="muted small mt-sm">On Chrome or Edge, use the browser menu and choose Install app or Add to Home screen when available. Offline access works after the app files are cached.</p>${deferredInstall?`<button class="btn secondary small mt-md" data-action="install">${icon('download')} Install Football Academy</button>`:''}</div>
 <div class="card pad"><h3>Backup & restore</h3><p class="muted small mt-sm">Export all student profiles, course results, and theme settings as one JSON file. Import on another device to transfer progress. Importing replaces existing local data, so export a backup first.</p><div class="flex wrap mt-md"><button class="btn secondary small" data-action="export">${icon('download')} Export JSON</button><button class="btn secondary small" data-action="trigger-import">${icon('upload')} Import JSON</button><input type="file" id="import-input" accept="application/json,.json" class="sr-only" aria-label="Import academy backup"></div><div class="keyline"></div><h3>Reset current student</h3><p class="muted small mt-sm">Remove this student’s lessons and scores. This cannot be undone without a backup.</p><button class="btn danger small mt-md" data-action="delete-profile">${icon('trash')} Delete student profile</button></div></div></div>`}
function modal(){if(!person()||model.dialog==='new-profile')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="welcome-heading"><div class="brand-icon">FA</div><div class="eyebrow mt-md">WELCOME TO THE ACADEMY</div><h2 id="welcome-heading">${person()?'Add a new student':'What should we call you?'}</h2><p>Enter a first name or nickname. Your progress, levels, and scores will stay associated with that name on this device. No account or email required.</p><form data-form="new-profile"><label class="label-field" for="new-name">Student name</label><input class="input" id="new-name" name="name" maxlength="40" minlength="1" required autocomplete="nickname" placeholder="Enter name" autofocus><button class="btn full" type="submit">${icon('arrow')} Enter the academy</button>${person()?'<button type="button" class="btn ghost full" data-action="close-dialog">Cancel</button>':''}</form></div></div>`;
 if(model.dialog==='confirm-delete')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="eyebrow">DELETE STUDENT PROFILE</div><h2>Delete ${E(person().name)}?</h2><p>This removes the student’s progress and name from this browser. Export a JSON backup first if you want to preserve it.</p><div class="flex wrap"><button class="btn danger" data-action="confirm-delete">Delete profile</button><button class="btn secondary" data-action="close-dialog">Cancel</button></div></div></div>`;
 if(model.dialog==='confirm-import')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="eyebrow">BACKUP RESTORE</div><h2>Replace local progress?</h2><p>Importing this backup will replace every student profile on this device. Export your current progress before continuing.</p><div class="flex wrap"><button class="btn" data-action="confirm-import">Restore backup</button><button class="btn secondary" data-action="close-dialog">Cancel</button></div></div></div>`;
 return ''}
function render(){document.body.dataset.theme=db.theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',db.theme==='dark'?'#10171b':'#f3f6f4');const screen=({dashboard,course,positions:positionsScreen,position:positionScreen,lesson:lessonScreen,designer:()=>designerStudio(practiceLevel(),practiceChooser()),simulator:()=>simulatorStudio(practiceLevel(),practiceChooser()),film:()=>filmStudio(practiceLevel(),practiceChooser()),progress:progressScreen,settings:settingsScreen})[model.view]||dashboard;document.getElementById('app').innerHTML=header()+screen()+footer()+modal()+(model.toast?`<div role="status" style="position:fixed;bottom:20px;right:20px;z-index:30;max-width:min(90vw,420px);background:var(--panel-alt);color:var(--text);border:1px solid var(--line-strong);border-radius:13px;padding:13px 17px;box-shadow:0 10px 30px var(--shadow)">${E(model.toast)}</div>`:'');}
function exportJson(){const blob=new Blob([JSON.stringify({format:'football-academy-backup',version:1,exported:now(),data:db},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='football-academy-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded. Keep the file somewhere safe.')}
function validateImport(payload){if(payload?.format!=='football-academy-backup'||payload?.version!==1||!Array.isArray(payload?.data?.profiles))throw Error('Not a compatible Football Academy backup.');if(payload.data.profiles.length>30)throw Error('Too many student profiles in backup.');const profiles=payload.data.profiles.map((u,i)=>{if(typeof u.name!=='string'||u.name.trim().length===0||u.name.length>40||typeof u.completed!=='object'||!u.completed)throw Error('Invalid student profile data.');const completed={};for(const [k,v] of Object.entries(u.completed)){if(!byId[k]||typeof v!=='object'||!v)continue;const best=clamp(Number(v.best)||0,0,100);completed[k]={best,attempts:clamp(Number(v.attempts)||0,0,9999),passed:Boolean(v.passed)&&best>=80,last:typeof v.last==='string'?v.last:now()}}return {id:'student-import-'+i+'-'+Date.now(),name:u.name,completed,xp:clamp(Number(u.xp)||0,0,100000),practiceLevel:['rookie','starter','allpro'].includes(u.practiceLevel)?u.practiceLevel:'rookie',created:typeof u.created==='string'?u.created:now()}});if(!profiles.length)throw Error('The backup contains no student profiles.');return {theme:payload.data.theme==='light'?'light':'dark',profiles,activeId:profiles[0].id};}
setupStudio(render);
const app=document.getElementById('app');
app.addEventListener('click',ev=>{const el=ev.target.closest('[data-go],[data-action],[data-lesson],[data-filter],[data-position],[data-answer],[data-select],[data-role],[data-sim-situation],[data-practice-level],[data-film],[data-film-answer],[data-sim-play],[data-switch],[data-theme],[data-studio],[data-studio-player],[data-studio-inspect]');if(!el||!app.contains(el))return;if(studioClick(el,practiceLevel(),model.view))return;
 if(el.dataset.go){navigate(el.dataset.go);return}
 if(el.dataset.lesson){openLesson(el.dataset.lesson);return}
 if(el.dataset.filter){model.filter=el.dataset.filter;render();return}
 if(el.dataset.position){model.positionId=el.dataset.position;model.view='position';window.scrollTo(0,0);render();return}
 if(el.dataset.role){model.playHighlight=model.playHighlight===el.dataset.role?'':el.dataset.role;render();return}
 if(el.dataset.answer!==undefined){if(model.quiz&&!model.quiz.submitted){model.quiz.answers[model.quiz.index]=Number(el.dataset.answer);render()}return}
 if(el.dataset.simSituation){model.sim=newSim(el.dataset.simSituation);render();return}
 if(el.dataset.practiceLevel){const level=el.dataset.practiceLevel;if(!['rookie','starter','allpro'].includes(level))return;person().practiceLevel=level;write();resetStudioForDifficulty();model.filmStep=0;model.filmAnswer=null;model.playStep=0;model.sim=newSim(model.sim?.challenge||'drive');render();return}
 if(el.dataset.film){model.filmId=el.dataset.film;model.filmStep=0;model.filmAnswer=null;render();return}
 if(el.dataset.filmAnswer!==undefined){model.filmAnswer=Number(el.dataset.filmAnswer);render();return}
 if(el.dataset.simPlay){simPlay(el.dataset.simPlay);return}
 if(el.dataset.switch){db.activeId=el.dataset.switch;write();model.view='dashboard';render();return}
 if(el.dataset.theme){db.theme=el.dataset.theme;write();render();return}
 switch(el.dataset.action){
  case 'toggle-theme':db.theme=db.theme==='dark'?'light':'dark';write();render();break;
  case 'toggle-menu':model.menu=!model.menu;render();break;
  case 'close-menu':model.menu=false;render();break;
  case 'lesson-back':navigate(byId[model.lessonId]?.positionId?'position':'course');break;
  case 'previous-concept':model.concept=Math.max(0,model.concept-1);render();break;
  case 'next-concept':{const l=byId[model.lessonId];if(model.concept<l.concepts.length-1)model.concept++;else model.quiz={answers:{},index:0,submitted:false,questions:drawCheckpoint(l)};render();break}
  case 'previous-question':model.quiz.index=Math.max(0,model.quiz.index-1);render();break;
  case 'next-question':{const l=byId[model.lessonId];const q=model.quiz;if(q.answers[q.index]===undefined)return;if(q.index<q.questions.length-1)q.index++;else {let correct=q.questions.filter((z,i)=>Number(q.answers[i])===Number(z[2])).length;q.score=Math.round(correct/q.questions.length*100);q.submitted=true;saveCompletion(l,q.score)}render();break}
  case 'restart-quiz':{const l=byId[model.lessonId];model.quiz={answers:{},index:0,submitted:false,questions:drawCheckpoint(l,model.quiz?.questions||[])};render();break}
  case 'play-step-back':model.playStep=Math.max(0,model.playStep-1);render();break;
  case 'play-step-next':model.playStep=(model.playStep+1)%4;render();break;
  case 'play-reset':model.playStep=0;render();break;
  case 'film-back':model.filmStep=Math.max(0,model.filmStep-1);render();break;
  case 'film-next':model.filmStep=Math.min(3,model.filmStep+1);render();break;
  case 'film-reset':model.filmStep=0;model.filmAnswer=null;render();break;
  case 'sim-reset':model.sim=newSim(model.sim?.challenge||'drive');render();break;
  case 'sim-timeout':if(model.sim&&!model.sim.over&&model.sim.timeouts>0){model.sim.timeouts--;model.sim.log.unshift('Timeout called. The game clock is stopped.');model.sim.message='Timeout used to discuss the next call.';render()}break;
  case 'sim-kick':simKick();break;
  case 'add-profile':model.dialog='new-profile';render();break;
  case 'close-dialog':model.dialog=null;render();break;
  case 'export':exportJson();break;
  case 'trigger-import':document.getElementById('import-input')?.click();break;
  case 'confirm-import':if(model.pendingImport){db=model.pendingImport;model.pendingImport=null;model.dialog=null;write();navigate('dashboard');notify('Backup restored. All student progress is available.')}break;
  case 'delete-profile':model.dialog='confirm-delete';render();break;
  case 'confirm-delete':db.profiles=db.profiles.filter(p=>p.id!==db.activeId);db.activeId=db.profiles[0]?.id||null;model.dialog=null;write();navigate('dashboard');break;
  case 'install':if(deferredInstall){deferredInstall.prompt();deferredInstall=null}break;
 }
});
app.addEventListener('change',ev=>{const el=ev.target;if(studioChange(el,practiceLevel()))return;if(el.dataset.select==='play'){model.playId=el.value;model.playStep=0;render()}if(el.dataset.select==='defense'){model.defenseId=el.value;model.playStep=0;render()}if(el.id==='import-input'){const f=el.files?.[0];if(!f)return;if(f.size>2_000_000){notify('Backup file too large.');return}f.text().then(t=>{try{model.pendingImport=validateImport(JSON.parse(t));model.dialog='confirm-import';render()}catch(e){notify(e.message)}}).catch(()=>notify('Could not read backup file.'))}});
app.addEventListener('submit',ev=>{const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const name=String(new FormData(form).get('name')||'').trim();if(!name){notify('Enter a student name first.');return}if(form.dataset.form==='new-profile'){createPerson(name);model.dialog=null;model.view='dashboard';render()}else if(form.dataset.form==='rename'){const p=person();p.name=name.slice(0,40);write();notify('Student name updated.')}});
render();
